/* prog49_bst.c – rebuilt from the obfuscated binary */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

/* Global tree root */
static Node *root = NULL;

/* Insert a value into the binary‑search‑tree */
static void insert(long v)
{
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = v;
    n->left = n->right = NULL;

    if (root == NULL) {
        root = n;
        return;
    }

    Node *cur = root;
    while (1) {
        if (v < cur->value) {
            if (cur->left == NULL) {
                cur->left = n;
                return;
            }
            cur = cur->left;
        } else {
            if (cur->right == NULL) {
                cur->right = n;
                return;
            }
            cur = cur->right;
        }
    }
}

/* Helper for printing a space before every element except the first */
static int printed = 0;
static void print_val(long v)
{
    if (printed) {
        putchar(' ');
    }
    printf("%ld", v);
    printed = 1;
}

/* Traversals */
static void inorder(Node *p)
{
    if (p == NULL) return;
    inorder(p->left);
    print_val(p->value);
    inorder(p->right);
}

static void preorder(Node *p)
{
    if (p == NULL) return;
    print_val(p->value);
    preorder(p->left);
    preorder(p->right);
}

static void postorder(Node *p)
{
    if (p == NULL) return;
    postorder(p->left);
    postorder(p->right);
    print_val(p->value);
}

/* Main driver */
int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    int preorder_flag = 0, inorder_flag = 0, postorder_flag = 0;

    if (strcmp(mode, "in") == 0) {
        inorder_flag = 1;
    } else if (strcmp(mode, "pre") == 0) {
        preorder_flag = 1;
    } else if (strcmp(mode, "post") == 0) {
        postorder_flag = 1;
    } else {
        puts("INVALID_MODE");
        return 0;
    }

    /* Build the BST from the remaining arguments */
    for (int i = 2; i < argc; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* the original program ignored errors */
        insert(v);
    }

    if (root == NULL) {
        puts("EMPTY");
        return 0;
    }

    printed = 0;
    if (inorder_flag)      inorder(root);
    else if (preorder_flag) preorder(root);
    else if (postorder_flag) postorder(root);
    putchar('\n');

    return 0;
}
